import { b, type Exercise, type Text } from './content';
export type Paper = {id:string;title:Text;minutes:number;intro:Text;questions:Exercise[]};
const item=(id:string,criterion:string,en:string,ru:string,ae:string,ar:string):Exercise=>({id,criterion,marks:25,prompt:b(en,ru),answer:b(ae,ar)});
export const papers:Paper[]=[{
 id:'biology',title:b('Biology · full rehearsal','Биология · полная репетиция'),minutes:120,
 intro:b('Four 25-mark sections. The school confirms a two-hour assessment with equal weighting of A–D. This is an original rehearsal, not an IB or school paper. Use the embedded lessons after the timed attempt. All tables below contain invented practice data.','Четыре раздела по 25 баллов. Школа указывает двухчасовой экзамен с равным весом A–D. Это авторская репетиция, не работа IB или школы. Уроки открывайте после попытки на время. Все данные ниже придуманы для практики.'),
 questions:[
 item('bio-A','A','(a) Compare bacterial, animal and plant cells: nucleus, cell wall, chloroplasts and ribosomes [6]. (b) A 40 mm image represents an 80 μm cell: calculate magnification with units converted [3]. (c) Explain absorption adaptations of the ileum and distinguish absorption from digestion [5]. (d) Explain vaccination and why antibiotics do not treat viruses [5]. (e) Explain negative feedback when blood glucose rises [6].','(a) Сравни бактериальную, животную и растительную клетки: ядро, стенка, хлоропласты, рибосомы [6]. (b) Изображение 40 мм соответствует клетке 80 мкм: найди увеличение [3]. (c) Объясни приспособления подвздошной кишки и отличие всасывания от переваривания [5]. (d) Объясни вакцинацию и неэффективность антибиотиков против вирусов [5]. (e) Объясни отрицательную обратную связь при повышении глюкозы [6].',
 'Award one mark per distinct correct point, up to each subpart cap. (a) Bacteria have no membrane-bound nucleus; plant and animal cells do. Bacterial and plant walls differ chemically; animal cells have no wall. Photosynthetic plant cells have chloroplasts; animal/bacterial cells do not have chloroplasts. All three have ribosomes [6]. (b) 40 mm=40000 μm; 40000/80; ×500 [3]. (c) Digestion hydrolyses large molecules; absorption transfers products across the gut wall; villi/microvilli enlarge area; thin epithelium shortens transport path; blood/lymph transport maintains uptake [5]. (d) Vaccine antigens stimulate a specific response; memory cells persist; later response is faster; viruses depend on host machinery; antibiotics target bacterial structures/processes [5]. (e) Rise detected by pancreatic beta cells; insulin released; responsive tissues increase uptake; liver/muscle increase glycogen storage; blood glucose falls; reduced stimulus reduces insulin secretion [6].',
 'По одному баллу за отдельный верный пункт в пределах подзадания. (a) У бактерии нет оформленного ядра, у растений и животных есть; стенки растений и бактерий различаются, у животных стенки нет; хлоропласты есть у фотосинтезирующих растительных клеток, но не у животных или бактерий; рибосомы есть у всех [6]. (b) 40000 мкм; деление на 80; ×500 [3]. (c) Расщепление молекул, перенос продуктов через стенку, большая поверхность, тонкий эпителий, отвод кровью/лимфой [5]. (d) Антиген, специфический ответ, память, ускоренный повторный ответ; антибиотик действует на бактериальные структуры, которых у вируса нет [5]. (e) Бета-клетки, инсулин, усвоение глюкозы чувствительными тканями, запасание гликогена, снижение глюкозы, ослабление стимула секреции [6].'),
 item('bio-B','B','Design a potato-cylinder investigation into how sucrose concentration affects percentage mass change after 30 minutes. (a) State a precise question [3]. (b) Predict and explain the pattern [5]. (c) Define the independent/dependent variables and three controls [5]. (d) Give a reproducible method, range and repeats [8]. (e) Address two practical limitations or safety points [4].','Спроектируй опыт: влияние концентрации сахарозы на процентное изменение массы цилиндров картофеля через 30 мин. (a) Точный вопрос [3]. (b) Прогноз и объяснение [5]. (c) Независимая, зависимая и три контролируемые переменные [5]. (d) Воспроизводимый метод, диапазон, повторы [8]. (e) Два ограничения или меры безопасности [4].',
 '(a) Name sucrose concentration with units, percentage mass change and 30 min [3]. (b) Dilute solution gives net water entry; concentrated solution gives net exit; through partially permeable membranes; down water-potential gradient; near equal potential little net change [5]. (c) Concentration; 100(final−initial)/initial; same dimensions, temperature and immersion time [5]. (d) Five or more stated concentrations spanning the expected zero; same potato source; sufficient equal solution volumes; accurately record initial mass; immerse completely; remove at 30 min; blot consistently and reweigh; at least three independent cylinders per concentration and calculate mean/spread [8]. (e) Two explained points, e.g. cutting away from fingers and using a board; consistent blotting to avoid surface-water bias; tissue variation or 30 min not guaranteeing equilibrium [2+2]. Accept other workable controlled designs.',
 '(a) Концентрация с единицами, процент массы, 30 мин [3]. (b) Вода входит в разбавленном и выходит в концентрированном растворе; мембрана избирательна; перенос по градиенту водного потенциала; около равенства потенциалов малое суммарное изменение [5]. (c) Концентрация; 100(конечная−начальная)/начальная; размеры, температура, время [5]. (d) Не менее пяти концентраций по обе стороны ожидаемого нуля; один источник картофеля; одинаковые достаточные объёмы; начальная масса; полное погружение; 30 мин; одинаковое промокание и повторное взвешивание; по три независимых цилиндра, среднее и разброс [8]. (e) Две меры с объяснением: безопасное вырезание; одинаковое удаление поверхностной воды; учёт различий ткани и неполного установления равновесия [2+2]. Допустим иной воспроизводимый дизайн.'),
 item('bio-C','C','Practice data: sucrose concentration (mol/dm³) → three percentage mass changes: 0.0 → 11,12,13; 0.2 → 5,6,7; 0.4 → −1,0,1; 0.6 → −7,−6,−5; 0.8 → −13,−12,−11. (a) Calculate means and ranges [5]. (b) Draw a labelled graph and estimate the zero crossing [6]. (c) Describe and explain the pattern [6]. (d) Evaluate the claim “mass change is inversely proportional to concentration”; give two specific improvements [8].','Данные: концентрация (моль/дм³) → три изменения массы (%): 0,0 → 11,12,13; 0,2 → 5,6,7; 0,4 → −1,0,1; 0,6 → −7,−6,−5; 0,8 → −13,−12,−11. (a) Средние и размахи [5]. (b) График с подписями и оценка нуля [6]. (c) Описание и объяснение [6]. (d) Оцени обратную пропорциональность; предложи два конкретных улучшения [8].',
 '(a) Means 12,6,0,−6,−12%; every range is 2 percentage points [5 for correct processed rows]. (b) Concentration on x, mass change on y, both labels/units, sensible scales, accurate points, a suitable trend; crossing ≈0.40 mol/dm³ [6]. (c) Mass change decreases as concentration rises; cite two numbers; dilute solutions lead to water gain; concentrated solutions to loss; membrane and water potential explain direction; zero means no net mass change under tested conditions, not no molecular movement [6]. (d) Negative linear association does not establish y=k/x; at x=0 the inverse model is undefined; products xy are not constant; no exact internal concentration is proved. Improve concentration spacing near zero and increase independent repeats/control tissue variation, explaining the benefit of each [4+2+2].',
 '(a) Средние 12,6,0,−6,−12%; размах каждой серии 2 процентных пункта [5 за обработанные строки]. (b) Оси, единицы, масштаб, точки, тренд и пересечение около 0,40 моль/дм³ [6]. (c) Убывание с числовыми примерами; в разбавленном растворе поступление воды, в концентрированном потеря; мембрана и водный потенциал; ноль означает отсутствие суммарного изменения, а не остановку молекул [6]. (d) Убывающий линейный тренд не равен y=k/x; при x=0 обратная модель не определена; произведения xy непостоянны; точная концентрация клеточного сока не установлена. Улучшения: больше точек около нуля и независимых повторов/контроль ткани, каждое с объяснением [4+2+2].'),
 item('bio-D','D','A fictional detergent trial uses equal stained cloths, 5 g powder, 20-minute washes and three repeats. Enzyme powder removes 82% stain at 30°C and 40% at 70°C; non-enzyme powder removes 45% and 74%. Heating one wash uses 0.20 kWh at 30°C and 0.65 kWh at 70°C. (a) Explain enzyme action and the temperature pattern [8]. (b) Calculate heating-energy saving for 100 low-temperature rather than high-temperature washes; evaluate environmental, cost and skin-sensitivity implications [9]. (c) Give a justified conditional recommendation and identify evidence needed before generalising [8].','Условное испытание: одинаковые загрязнённые ткани, 5 г порошка, стирка 20 мин, три повтора. Ферментный порошок удаляет 82% пятна при 30 °C и 40% при 70 °C; без ферментов — 45% и 74%. Нагрев расходует 0,20 и 0,65 кВт·ч. (a) Механизм и температурная зависимость [8]. (b) Экономия нагрева за 100 стирок; среда, стоимость, чувствительность кожи [9]. (c) Обоснованная условная рекомендация и данные для обобщения [8].',
 '(a) Enzymes catalyse hydrolysis; active sites match substrates; protease acts on protein and lipase on fats; suitable temperature allows effective collisions; excessive heat can denature; active-site structure changes; data support reduced enzyme performance at 70°C but do not isolate denaturation from formulation effects; non-enzyme powder improves with heat in this trial [8]. (b) 0.65−0.20=0.45 kWh/wash; ×100=45 kWh saved [3]. Lower energy may reduce cost and emissions depending on tariffs/electricity mix; manufacture, packaging and wastewater still matter; irritation/allergy varies and is not diagnosed by this cleaning test; lower-temperature hygiene may require separate evidence [6]. (c) Recommend enzyme powder at 30°C for comparable stains if tolerated, tied to 82% vs 45% and heating data; note performance, material and hygiene constraints. Seek scatter/error bars, more stain types, longer-term fabric/skin data, product life-cycle evidence and real-machine tests. Award up to 8 for a balanced judgement with relevant evidence, not for a preferred opinion.',
 '(a) Катализ гидролиза, специфичность активного центра, протеаза/липаза, столкновения, денатурация, изменение центра, ограничение вывода по смеси порошка, рост эффективности неферментного при нагревании [8]. (b) 0,45 кВт·ч на стирку, 45 кВт·ч на 100 [3]; цена и выбросы зависят от тарифов и энергосистемы, остаются производство и стоки, возможна индивидуальная чувствительность, гигиена требует отдельной проверки [6]. (c) Условная рекомендация ферментного при 30 °C для сходных пятен при переносимости, с опорой на 82% против 45% и расход энергии. Нужны разброс, другие пятна, материалы, испытания реальных машин и жизненный цикл. До 8 за аргументированный вывод, а не за выбранную позицию.'),
 ]},
 {
 id:'physics',title:b('Physics · practice paper A–D','Физика · тренировочная работа A–D'),minutes:100,
 intro:b('Four sections, A–D, worth 25 marks each: 100 marks in total. Use the 100-minute timer for the full paper, about one minute per mark. The daily-plan portion A + C is 50 marks: use its 50-minute timer, then spend 15 minutes checking. These timings are study guides. Write calculations with units and show your reasoning. For the spring investigation take g = 10 N/kg.','Четыре раздела A–D по 25 баллов: всего 100 баллов. Для полной работы включи таймер на 100 минут — примерно минута на балл. Порция A + C из плана содержит 50 баллов: её таймер рассчитан на 50 минут, затем выдели 15 минут на проверку. Время служит учебным ориентиром. Показывай ход вычислений, указывай единицы и объясняй выводы. В опыте с пружиной прими g = 10 Н/кг.'),
 questions:[
 item('phy-A','A','(a) A 2.0 kg trolley accelerates uniformly from rest to 6.0 m/s in 3.0 s. Calculate its acceleration, resultant force and final kinetic energy [6].\n\n(b) A heater has a potential difference of 12 V and a current of 2.0 A for 60 s. Calculate its resistance, power and transferred energy [6].\n\n(c) A 0.10 kg sample of liquid water absorbs 8400 J without changing state. Its specific heat capacity is 4200 J/(kg·K). Calculate the temperature rise [3]. Explain this rise using the particle model [2].\n\n(d) A wave has frequency 50 Hz and wavelength 0.80 m. Calculate its speed [2]. Describe the direction of oscillation in transverse and longitudinal waves relative to propagation [2].\n\n(e) The background-corrected count rate of one radioactive isotope falls from 640 counts/min to 80 counts/min in 15 min. Calculate its half-life [3]. State what makes two atoms isotopes of the same element [1].','(a) Тележка массой 2,0 кг равноускоренно разгоняется из состояния покоя до 6,0 м/с за 3,0 с. Вычисли ускорение (acceleration), равнодействующую силу (resultant force) и конечную кинетическую энергию (kinetic energy) [6].\n\n(b) При напряжении (potential difference) 12 В через нагреватель 60 с идёт ток 2,0 А. Вычисли сопротивление (resistance), мощность (power) и переданную энергию [6].\n\n(c) Вода массой 0,10 кг получает 8400 Дж без изменения агрегатного состояния. Её удельная теплоёмкость (specific heat capacity) равна 4200 Дж/(кг·К). Вычисли повышение температуры [3]. Объясни это повышение с помощью модели частиц (particle model) [2].\n\n(d) Частота (frequency) волны равна 50 Гц, длина волны (wavelength) — 0,80 м. Вычисли скорость распространения [2]. Опиши направление колебаний относительно распространения у поперечной (transverse) и продольной (longitudinal) волны [2].\n\n(e) Скорость счёта одного радиоактивного изотопа после вычитания фона падает с 640 имп/мин до 80 имп/мин за 15 мин. Вычисли период полураспада (half-life) [3]. Укажи, чем отличаются изотопы (isotopes) одного элемента [1].',
 '(a) Let u and v be initial and final velocity (m/s), t time (s), m mass (kg), a acceleration (m/s²), F resultant force (N), and Ek kinetic energy (J).\n- a = (v − u)/t = (6.0 − 0) m/s ÷ 3.0 s = 2.0 m/s²: formula with substitution [1], result with unit [1].\n- F = ma = 2.0 kg × 2.0 m/s² = 4.0 N: method [1], result with unit [1].\n- Ek = ½mv² = ½ × 2.0 kg × (6.0 m/s)² = 36 J: method [1], result with unit [1]. Total [6].\n\n(b) V is potential difference (V), I current (A), R resistance (Ω), P power (W), E energy (J), and t time (s).\n- R = V/I = 12 V ÷ 2.0 A = 6.0 Ω [2].\n- P = VI = 12 V × 2.0 A = 24 W [2].\n- E = Pt = 24 W × 60 s = 1440 J [2]. Each pair awards one mark for method and one for the result with unit. Total [6].\n\n(c) Q is absorbed energy (J), m mass (kg), c specific heat capacity (J/(kg·K)), and ΔT temperature rise (K).\n- ΔT = Q/(mc) [1] = 8400 J ÷ (0.10 kg × 4200 J/(kg·K)) [1] = 20 K, a rise of 20 °C [1].\n- The particles gain average kinetic energy [1]; temperature measures this average, so it rises [1]. Total [5].\n\n(d) v is wave speed (m/s), f frequency (Hz), and λ wavelength (m). v = fλ = 50 Hz × 0.80 m [1] = 40 m/s [1]. Oscillations are perpendicular to propagation in a transverse wave [1] and parallel in a longitudinal wave [1]. Total [4].\n\n(e) 640 → 320 → 160 → 80 counts/min [1]: three half-lives [1]. Half-life T½ = elapsed time / number of halvings = 15 min / 3 = 5 min [1]. Isotopes have the same proton number but different neutron numbers [1]. Total [4].',
 '(a) Обозначения: v₀ и v — начальная и конечная скорости (м/с), t — время (с), m — масса (кг), a — ускорение (м/с²), F — равнодействующая сила (Н), Eк — кинетическая энергия (Дж).\n- a = (v − v₀)/t = (6,0 − 0) м/с ÷ 3,0 с = 2,0 м/с²: формула с подстановкой [1], результат с единицей [1].\n- F = ma = 2,0 кг × 2,0 м/с² = 4,0 Н: способ расчёта [1], результат с единицей [1].\n- Eк = ½mv² = ½ × 2,0 кг × (6,0 м/с)² = 36 Дж: способ расчёта [1], результат с единицей [1]. Всего [6].\n\n(b) U — напряжение (В; в английском обозначают V), I — сила тока (А), R — сопротивление (Ом), P — мощность (Вт), E — энергия (Дж), t — время (с).\n- R = U/I = 12 В ÷ 2,0 А = 6,0 Ом [2].\n- P = UI = 12 В × 2,0 А = 24 Вт [2].\n- E = Pt = 24 Вт × 60 с = 1440 Дж [2]. За каждый расчёт: способ [1], результат с единицей [1]. Всего [6].\n\n(c) Q — полученная энергия (Дж), m — масса (кг), c — удельная теплоёмкость (Дж/(кг·К)), ΔT — повышение температуры (К).\n- ΔT = Q/(mc) [1] = 8400 Дж ÷ (0,10 кг × 4200 Дж/(кг·К)) [1] = 20 К, то есть повышение на 20 °C [1].\n- Средняя кинетическая энергия частиц увеличивается [1]; температура характеризует эту среднюю энергию, поэтому растёт [1]. Всего [5].\n\n(d) v — скорость волны (м/с), ν — частота (Гц; в английском f), λ — длина волны (м). v = νλ = 50 Гц × 0,80 м [1] = 40 м/с [1]. В поперечной волне колебания перпендикулярны направлению распространения [1], в продольной — параллельны [1]. Всего [4].\n\n(e) 640 → 320 → 160 → 80 имп/мин [1]: прошло три периода полураспада [1]. Период полураспада T½ = время / число уменьшений вдвое = 15 мин / 3 = 5 мин [1]. У изотопов одинаковое число протонов и разное число нейтронов [1]. Всего [4].'),
 item('phy-B','B','Design an investigation into how the extension of a spring depends on the applied force. The spring is rated for loads up to 2.0 N; do not exceed this limit.\n\n(a) Formulate a precise research question [3].\n\n(b) Predict the relationship, explain it with a formula and state its limit [5].\n\n(c) Identify the independent and dependent variables and three controls [5].\n\n(d) Describe a reproducible method using at least five loads, repeats and a graph to determine spring constant [8].\n\n(e) Identify two specific risks or measurement problems and explain how to reduce each [4].','Спланируй опыт: как удлинение (extension) пружины зависит от приложенной силы. Допустимая нагрузка пружины — до 2,0 Н; не превышай её.\n\n(a) Сформулируй точный исследовательский вопрос [3].\n\n(b) Предскажи зависимость, объясни её формулой и укажи границу применимости [5].\n\n(c) Назови независимую (independent) и зависимую (dependent) переменные и три контролируемые величины или условия [5].\n\n(d) Опиши воспроизводимый опыт как минимум с пятью нагрузками, повторами и графиком для определения жёсткости пружины (spring constant) [8].\n\n(e) Назови две конкретные опасности или причины ошибок измерения и объясни, как уменьшить каждую [4].',
 '(a) Example: “How does applied force from 0 to 2.0 N affect the extension in metres of this spring?” Force and units [1], extension and units [1], a specific spring and range [1].\n\n(b) Extension should be proportional to force [1]. F = kx [1], where F is force (N), x extension (m) and k spring constant (N/m) [1]. The same spring has constant k within the proportional limit [1]; beyond that limit, proportionality fails [1].\n\n(c) Independent: applied force [1]. Dependent: extension [1]. Keep the spring [1], fixed support [1] and ruler position/reference point [1] unchanged.\n\n(d) One mark for each step:\n- Secure the spring and measure unloaded length L₀ (m) [1].\n- Use total suspended masses 0, 0.050, 0.100, 0.150 and 0.200 kg, including the hanger [1].\n- Calculate F = mg, where m is total suspended mass (kg) and g = 10 N/kg: forces are 0, 0.50, 1.0, 1.5 and 2.0 N [1].\n- Wait for oscillations to stop after adding each load [1].\n- Read the loaded length L (m) at eye level against a fixed ruler [1].\n- Calculate extension x = L − L₀ for each load [1].\n- Repeat the complete loading sequence three times, checking unloaded length each time, then find the mean extension for each force [1].\n- Plot F vertically against x horizontally; the gradient of the straight region is k = ΔF/Δx, in N/m [1]. Total [8].\n\n(e) Example pairs: falling masses can injure feet [1], so place a catch tray below and keep feet clear [1]. Viewing a ruler at an angle causes parallax [1], so use a pointer and read at eye level [1]. Other justified risk–precaution pairs are valid. Total [4].',
 '(a) Пример: «Как сила от 0 до 2,0 Н влияет на удлинение этой пружины, измеренное в метрах?» Сила с единицей [1], удлинение с единицей [1], конкретная пружина и диапазон [1].\n\n(b) Удлинение должно быть прямо пропорционально силе [1]. F = kx [1], где F — сила (Н), x — удлинение (м), k — жёсткость пружины (Н/м) [1]. У одной пружины k постоянно в пределах пропорциональности (proportional limit) [1]; за этим пределом пропорциональность нарушается [1].\n\n(c) Независимая переменная — приложенная сила [1], зависимая — удлинение [1]. Не меняй пружину [1], закрепление опоры [1], положение линейки и точку отсчёта [1].\n\n(d) По баллу за каждый шаг:\n- Закрепи пружину и измерь длину без нагрузки L₀ (м) [1].\n- Используй полные массы подвеса 0; 0,050; 0,100; 0,150; 0,200 кг, учитывая держатель грузов [1].\n- Вычисли F = mg, где m — полная масса подвеса (кг), g = 10 Н/кг. Получатся силы 0; 0,50; 1,0; 1,5; 2,0 Н [1].\n- После изменения нагрузки дождись прекращения колебаний [1].\n- Измерь длину L (м) по неподвижной линейке, глядя на отметку на уровне глаз [1].\n- Для каждой нагрузки вычисли удлинение x = L − L₀ [1].\n- Трижды повтори весь цикл нагрузок, каждый раз проверяя длину без груза; найди среднее удлинение при каждой силе [1].\n- Построй график: F по вертикали, x по горизонтали. Наклон прямого участка k = ΔF/Δx даёт жёсткость в Н/м [1]. Всего [8].\n\n(e) Примеры пар: падающий груз может травмировать стопу [1], поэтому поставь поддон и убери ноги из-под груза [1]. Взгляд на линейку под углом даёт ошибку параллакса (parallax) [1]; используй указатель и считывай на уровне глаз [1]. Принимаются другие обоснованные пары «опасность или ошибка — мера». Всего [4].'),
 item('phy-C','C','A different spring is tested. Applied forces F (N): 0, 1, 2, 3, 4. Corresponding extensions x (m): 0.000, 0.020, 0.040, 0.061, 0.100. The uncertainty in each extension is ±0.002 m. Treat force uncertainty as negligible.\n\n(a) Plot F against x on paper and calculate the spring constant from the first three points [6].\n\n(b) Analyse where the proportional model fits. Compare the 3 N and 4 N results with predictions, using the stated uncertainty [6].\n\n(c) Evaluate the claim: “The 4 N result proves the spring is permanently deformed” [5].\n\n(d) Suggest two improvements and explain their effects. State a conclusion with a supported range and limitations [8].','Испытывают другую пружину. Силы F (Н): 0; 1; 2; 3; 4. Соответствующие удлинения x (м): 0,000; 0,020; 0,040; 0,061; 0,100. Погрешность (uncertainty) каждого удлинения ±0,002 м. Погрешностью силы пренебреги.\n\n(a) На бумаге построй график F от x и вычисли жёсткость пружины (spring constant) по первым трём точкам [6].\n\n(b) Проанализируй, где данные согласуются с пропорциональной зависимостью. Сравни результаты при 3 Н и 4 Н с прогнозом, учитывая указанную погрешность [6].\n\n(c) Оцени утверждение: «Результат при 4 Н доказывает, что пружина получила остаточную деформацию (permanent deformation)» [5].\n\n(d) Предложи два улучшения опыта и объясни их действие. Сделай вывод с обоснованным диапазоном применимости и ограничениями [8].',
 '(a) Horizontal axis x in m [1]; vertical axis F in N [1]; sensible uniform scales [1]; all five points plotted correctly [1]. The gradient gives spring constant k (N/m). Here ΔF is the change in force (N) and Δx the change in extension (m).\n\nk = ΔF/Δx [1] = ((2 − 0) N) / ((0.040 − 0.000) m) = 50 N/m [1]. Total for (a): [6].\n\n(b) The 0–2 N points lie on a straight line through the origin [1]. From x = F/k, the prediction at 3 N is 3 N ÷ (50 N/m) = 0.060 m [1]. The difference is 0.001 m, within ±0.002 m [1]. At 4 N the prediction is 4 N ÷ (50 N/m) = 0.080 m [1]. The observed excess is 0.100 − 0.080 = 0.020 m, much larger than the stated uncertainty [1]. Thus the proportional model is consistent up to 3 N but not with the 4 N measurement [1]. Total [6].\n\n(c) The claim is not proven [1]. A reading or recording error could explain a single point [1]. Remove the load and remeasure the unloaded length [1]; a lasting increase would show permanent deformation [1]. The proportional limit and elastic limit are different: non-proportional stretching may still be reversible [1]. Total [5].\n\n(d) Repeat measurements near 4 N [1] to test whether the departure is reproducible or a one-off error [1]. Use smaller load increments between 3 N and 4 N [1] to locate the departure more closely [1]. Conclusion: the tested spring is consistent with F = kx for 0–3 N [1], with k about 50 N/m [1]. Do not extrapolate this relation above 3 N [1]. One reading at each load limits confidence; unloading and repeat data are still needed [1]. Total [8].',
 '(a) По горизонтали x в метрах [1], по вертикали F в ньютонах [1]; равномерные удобные масштабы [1]; все пять точек нанесены верно [1]. Наклон графика даёт жёсткость k (Н/м). Здесь ΔF — изменение силы (Н), Δx — изменение удлинения (м).\n\nk = ΔF/Δx [1] = ((2 − 0) Н) / ((0,040 − 0,000) м) = 50 Н/м [1]. Всего за (a): [6].\n\n(b) Точки 0–2 Н лежат на прямой через начало координат [1]. По формуле x = F/k при 3 Н ожидается 3 Н ÷ (50 Н/м) = 0,060 м [1]. Отличие 0,001 м укладывается в ±0,002 м [1]. При 4 Н прогноз: 4 Н ÷ (50 Н/м) = 0,080 м [1]. Измеренное удлинение больше на 0,100 − 0,080 = 0,020 м — намного больше указанной погрешности [1]. Значит, данные до 3 Н согласуются с пропорциональной моделью, а точка 4 Н — нет [1]. Всего [6].\n\n(c) Утверждение не доказано [1]. Одиночная точка может быть ошибкой измерения или записи [1]. Нужно снять груз и снова измерить исходную длину [1]; сохраняющееся увеличение длины укажет на остаточную деформацию [1]. Предел пропорциональности (proportional limit) и предел упругости (elastic limit) различаются: непропорциональное растяжение ещё может быть обратимым [1]. Всего [5].\n\n(d) Повтори измерения около 4 Н [1], чтобы отличить устойчивое отклонение от случайной ошибки [1]. Уменьши шаг нагрузки между 3 Н и 4 Н [1], чтобы точнее найти границу отклонения [1]. Вывод: для испытанной пружины данные 0–3 Н согласуются с F = kx [1], где k примерно 50 Н/м [1]. Не переноси эту зависимость на силы выше 3 Н [1]. Единственное измерение при каждой нагрузке ограничивает уверенность: нужны повторы и проверка после разгрузки [1]. Всего [8].'),
 item('phy-D','D','A community centre compares rooftop photovoltaic panels with a solar thermal water heater. Photovoltaic installation costs £18 000. Expected annual electricity generation is 10 000 kWh; each kWh used on site saves £0.20.\n\n(a) Explain how photovoltaic panels supply electricity and how a solar thermal heater differs. Explain why sunlight is a renewable energy resource [7].\n\n(b) Calculate the annual saving and simple payback time, assuming all generated electricity is used on site. Evaluate three assumptions behind using this payback estimate [8].\n\n(c) Discuss two environmental benefits and two limitations of the photovoltaic option, explaining each. Justify a recommendation with a condition that should be checked [10].','Общественный центр сравнивает фотоэлектрические панели (photovoltaic panels) на крыше с солнечным водонагревателем (solar thermal water heater). Установка панелей стоит 18 000 фунтов. Ожидаемая выработка — 10 000 кВт·ч в год; каждый кВт·ч, использованный в здании, экономит 0,20 фунта.\n\n(a) Объясни, как фотоэлектрические панели дают электричество и чем отличается солнечный водонагреватель. Объясни, почему солнечный свет относят к возобновляемым ресурсам (renewable resources) [7].\n\n(b) Вычисли годовую экономию и простой срок окупаемости (simple payback time), считая, что вся выработанная энергия используется в здании. Оцени три допущения, от которых зависит эта оценка окупаемости [8].\n\n(c) Рассмотри два экологических преимущества и два ограничения панелей, объясняя каждое. Обоснуй рекомендацию и укажи условие, которое нужно проверить [10].',
 '(a) Award one mark for each connected point:\n- Light carries energy as electromagnetic radiation [1].\n- In a photovoltaic semiconductor, absorbed light transfers energy to charge carriers [1].\n- Separated charges drive a direct current in a connected circuit [1].\n- An inverter can convert this DC output to AC for the building [1].\n- A solar thermal heater transfers absorbed solar energy directly to a fluid as heating, rather than first producing electricity [1].\n- Neither system burns fuel while collecting sunlight [1].\n- Sunlight is continuously supplied on human timescales, so using it does not deplete a finite fuel stock [1]. Total [7].\n\n(b) Annual saving S = generated energy × saving per kWh = 10 000 kWh/year × £0.20/kWh = £2000/year [1]. Simple payback t = installation cost / annual saving = £18 000 / (£2000/year) = 9 years [1]. S is a money saving per year and t is a time in years.\n- All energy is assumed to be used on site [1]; exported energy may earn a different price, changing the saving [1].\n- Annual generation is assumed constant [1]; shading, weather and panel degradation may reduce output and lengthen payback [1].\n- The estimate omits maintenance, inverter replacement and finance costs [1]; including them may lengthen payback [1]. Total [8].\n\n(c) Example evaluation:\n- Replacing fossil-fuel electricity can reduce operational carbon dioxide emissions [1], because less fuel needs to be burned elsewhere [1].\n- It can also reduce operational air pollutants such as sulfur dioxide [1], if the displaced generator burns sulfur-containing fuel [1].\n- Mining materials and manufacturing panels have environmental impacts [1], so operation alone does not represent the whole life cycle [1].\n- Output varies and stops at night [1], so storage or other generation is needed when demand exceeds supply [1].\n- Recommend panels if the roof and daytime demand are suitable [1]; check that expected useful life and net savings justify the cost beyond the nine-year simple estimate [1]. Total [10]. Accept other scientifically supported benefits, limitations and conditional judgements within the same caps.',
 '(a) По баллу за каждое звено объяснения:\n- Свет переносит энергию в виде электромагнитного излучения [1].\n- В полупроводнике фотоэлемента поглощённый свет передаёт энергию носителям заряда [1].\n- Разделение зарядов создаёт постоянный ток (DC) в замкнутой внешней цепи [1].\n- Инвертор может преобразовать его в переменный ток (AC) для здания [1].\n- Солнечный водонагреватель передаёт поглощённую энергию непосредственно жидкости в виде теплоты, без предварительного получения электричества [1].\n- При сборе солнечной энергии обе установки обходятся без сжигания топлива [1].\n- Солнечное излучение непрерывно поступает в масштабе человеческой жизни; его использование не истощает конечный запас топлива [1]. Всего [7].\n\n(b) Годовая экономия S = выработка × экономия за кВт·ч = 10 000 кВт·ч/год × 0,20 фунта/(кВт·ч) = 2000 фунтов/год [1]. Простой срок окупаемости t = стоимость / годовая экономия = 18 000 фунтов / (2000 фунтов/год) = 9 лет [1]. S — денежная экономия за год, t — время в годах.\n- Предполагается, что вся энергия используется в здании [1]; за передачу излишков в сеть могут платить иначе, и экономия изменится [1].\n- Выработка считается постоянной по годам [1]; тень, погода и старение панелей могут уменьшить её и увеличить срок окупаемости [1].\n- Не учтены обслуживание, замена инвертора и стоимость финансирования [1]; с учётом этих затрат окупаемость может наступить позже [1]. Всего [8].\n\n(c) Пример оценки:\n- Замещение электричества из ископаемого топлива может снизить выбросы углекислого газа при выработке электричества [1], поскольку на другой станции понадобится сжечь меньше топлива [1].\n- Могут уменьшиться и выбросы загрязняющих веществ, например диоксида серы [1], если замещаемая станция сжигает серосодержащее топливо [1].\n- Добыча сырья и производство панелей влияют на окружающую среду [1], поэтому нельзя оценивать весь жизненный цикл только по работе установки [1].\n- Выработка меняется и прекращается ночью [1]; когда потребление выше выработки, нужен накопитель или другой источник электричества [1].\n- Панели можно рекомендовать при подходящей крыше и достаточном дневном потреблении [1]; нужно проверить срок службы и чистую экономию с учётом затрат за пределами простой девятилетней оценки [1]. Всего [10]. Принимай другие научно обоснованные преимущества, ограничения и условные выводы в тех же пределах баллов.'),
 ]},
 {
 id:'chemistry',title:b('Chemistry · practice paper A–D','Химия · тренировочная работа A–D'),minutes:100,
 intro:b('This practice paper is worth 100 marks. Each criterion (A–D) is worth 25 marks. The daily plan selects Criteria A and C: 50 minutes to attempt, then 15 minutes to check; the full paper remains available. Parts marked (Extended) go beyond the core level; attempt them only if they are assigned.','Тренировочная работа на 100 баллов. Каждый критерий (A–D) стоит 25 баллов. По плану выбери критерии A и C: 50 минут на попытку, затем 15 на проверку; полная работа остаётся доступной. Части с пометкой (Extended) выходят за рамки основного уровня; выполняй их, только если их назначили.'),
 questions:[
 item('chem-A','A','(a) Compare ionic and simple molecular substances. Explain the differences in their melting points and electrical conductivity [6].\n\n(b) Magnesium reacts with hydrochloric acid: Mg(s) + 2HCl(aq) → MgCl₂(aq) + H₂(g). Starting with 2.4 g of Mg (M = 24 g/mol) and excess acid, calculate the number of moles of Mg and of H₂ [4].\n\n(c) In a separate experiment, the theoretical yield is 5.0 g, but the actual yield is 4.0 g. Calculate the percentage yield [2]. (Extended) Explain what atom economy measures and how it differs from percentage yield [2].\n\n(d) Explain what happens during the electrolysis of molten sodium chloride [3]. (Extended) Write the half-equations at each electrode [2].\n\n(e) (Extended) Explain how increasing the pressure and adding a catalyst affect the equilibrium N₂(g) + 3H₂(g) ⇌ 2NH₃(g) at a fixed temperature [6].','(a) Сравни ионные и молекулярные вещества. Объясни различия в температуре плавления и в электропроводности [6].\n\n(b) Магний реагирует с соляной кислотой: Mg(s) + 2HCl(aq) → MgCl₂(aq) + H₂(g). Из 2,4 г магния (M = 24 г/моль) при избытке кислоты вычисли количество вещества (в молях) магния и водорода [4].\n\n(c) В отдельном опыте теоретический выход равен 5,0 г, а фактический — 4,0 г. Вычисли выход продукта в процентах [2]. (Extended) Объясни, что показывает атомная экономичность (atom economy) и чем она отличается от выхода продукта в процентах [2].\n\n(d) Объясни, что происходит при электролизе (electrolysis) расплава хлорида натрия [3]. (Extended) Запиши полуреакции (half-equations) у каждого электрода [2].\n\n(e) (Extended) Объясни, как повышение давления и добавление катализатора (catalyst) влияют на равновесие N₂(g) + 3H₂(g) ⇌ 2NH₃(g) при постоянной температуре [6].',
 '(a) Ionic substances form a giant lattice of oppositely charged ions. Strong electrostatic attraction between the ions needs a lot of energy to overcome, so the melting point is high. In the solid, the ions are fixed in place and cannot carry charge. When molten or dissolved, the ions move freely and conduct electricity. Simple molecular substances have strong covalent bonds inside each molecule but weak intermolecular forces between molecules. Little energy is needed to separate the molecules, so the melting point is low. They contain no ions or delocalised electrons, so they do not conduct when solid or molten [6].\n\n(b) Mg(s) + 2HCl(aq) → MgCl₂(aq) + H₂(g). n(Mg) = m ÷ M = 2.4 g ÷ 24 g/mol = 0.10 mol. The acid is in excess, so all the magnesium reacts. The equation shows that 1 mol of Mg gives 1 mol of H₂, so n(H₂) = 0.10 mol [4].\n\n(c) Percentage yield = actual ÷ theoretical × 100 = 4.0 g ÷ 5.0 g × 100 = 80% [2]. Atom economy is the percentage of the reactants’ mass that ends up in the desired product, calculated from the equation. It is a theoretical value. Unlike percentage yield, it does not depend on how much product is actually collected [2].\n\n(d) The molten salt contains mobile Na⁺ and Cl⁻ ions. At the cathode (negative electrode), each Na⁺ ion gains one electron, which is reduction: Na⁺(l) + e⁻ → Na(l). At the anode (positive electrode), each Cl⁻ ion loses one electron, which is oxidation: 2Cl⁻(l) → Cl₂(g) + 2e⁻. Overall: 2NaCl(l) → 2Na(l) + Cl₂(g) [3]. (Extended) Half-equations at each electrode, as above [2].\n\n(e) (Extended) Increasing the pressure moves the equilibrium towards the side with fewer gas molecules. The left side has 1 + 3 = 4 mol of gas and the right side has 2 mol, so the equilibrium moves right, more NH₃ forms and the yield increases [4]. A catalyst speeds up the forward and reverse reactions by the same amount. At a fixed temperature it does not change the position of equilibrium or the yield, but equilibrium is reached sooner [2].',
 '(a) Ионные вещества образуют ионную кристаллическую решётку из противоположно заряженных ионов. Чтобы преодолеть сильное электростатическое притяжение между ионами, нужно много энергии, поэтому температура плавления высокая. В твёрдом веществе ионы закреплены на местах и не переносят заряд. В расплаве или растворе ионы свободно движутся и проводят ток. У молекулярных веществ внутри молекул действуют прочные ковалентные связи, а между молекулами — слабые межмолекулярные взаимодействия. Чтобы разорвать эти слабые взаимодействия, нужно мало энергии, поэтому температура плавления низкая. Ионов и делокализованных электронов (delocalised electrons) в них нет, поэтому в твёрдом и расплавленном виде такие вещества ток не проводят [6].\n\n(b) Mg(s) + 2HCl(aq) → MgCl₂(aq) + H₂(g). n(Mg) = m ÷ M = 2,4 г ÷ 24 г/моль = 0,10 моль. Кислота в избытке, поэтому весь магний реагирует. По уравнению 1 моль Mg даёт 1 моль H₂, значит, n(H₂) = 0,10 моль [4].\n\n(c) Выход продукта (в процентах) = фактический ÷ теоретический × 100 = 4,0 г ÷ 5,0 г × 100 = 80 % [2]. Атомная экономичность — это процент массы реагентов, которая переходит в нужный продукт; её считают по уравнению реакции. Это расчётная величина. В отличие от выхода продукта в процентах, она не зависит от того, сколько продукта получили на практике [2].\n\n(d) Расплав содержит подвижные ионы Na⁺ и Cl⁻. На катоде (cathode, отрицательный электрод) каждый ион Na⁺ присоединяет один электрон. Это восстановление (reduction): Na⁺(l) + e⁻ → Na(l). На аноде (положительном электроде) каждый ион Cl⁻ отдаёт один электрон. Это окисление (oxidation): 2Cl⁻(l) → Cl₂(g) + 2e⁻. Суммарно: 2NaCl(l) → 2Na(l) + Cl₂(g) [3]. (Extended) Полуреакции у каждого электрода, как выше [2].\n\n(e) (Extended) Повышение давления смещает равновесие в сторону меньшего числа молекул газа. Слева 1 + 3 = 4 моль газа, справа 2 моль газа. Поэтому равновесие смещается вправо, образуется больше NH₃, и выход растёт [4]. Катализатор одинаково ускоряет прямую и обратную реакции. При постоянной температуре он не меняет положение равновесия и выход, но равновесие наступает быстрее [2].'),
 item('chem-B','B','Design an investigation into how the surface area of marble chips affects the initial rate of reaction with dilute hydrochloric acid.\n\n(a) State a research question that names the variables [3].\n\n(b) Write a hypothesis and explain it using collision theory [5].\n\n(c) Describe the independent, dependent and controlled variables [5].\n\n(d) Describe the method, including how you will collect and process the data [8].\n\n(e) Explain two safety precautions and two steps that keep the results valid [4].','Спроектируй опыт, чтобы выяснить, как площадь поверхности (surface area) мраморной крошки влияет на начальную скорость химической реакции (rate of reaction) с разбавленной соляной кислотой (HCl).\n\n(a) Назови исследовательский вопрос, в котором указаны переменные [3].\n\n(b) Сформулируй гипотезу и объясни её, опираясь на теорию столкновений (collision theory) [5].\n\n(c) Опиши независимую, зависимую и контролируемые переменные [5].\n\n(d) Опиши метод, включая сбор и обработку данных [8].\n\n(e) Объясни две меры безопасности и два шага, которые делают результаты достоверными [4].',
 '(a) A good question names the variable you change (particle size, or surface area, of the marble), the variable you measure (initial rate of CO₂ production, in cm³ s⁻¹) and the reaction. For example: How does the surface area of marble chips affect the initial rate of CO₂ production? Reaction: CaCO₃(s) + 2HCl(aq) → CaCl₂(aq) + H₂O(l) + CO₂(g) [3].\n\n(b) Hypothesis: smaller chips give a faster initial rate. Chips of the same mass but smaller size have a larger total surface area. More acid particles reach the solid surface each second, so more effective collisions happen per second and the reaction starts faster. The total volume of CO₂ does not change, because the same mass of marble gives the same amount of gas when the acid is in excess [5].\n\n(c) Independent variable: particle size (surface area) of the marble. Dependent variable: the volume of CO₂ collected in the first seconds, which gives the initial rate (cm³ s⁻¹). Controlled variables: mass of marble, volume and concentration of the acid (in excess), and temperature. Surface area is not easy to measure, so particle size is used as an estimate of it [5].\n\n(d) Sieve the marble into at least five defined size ranges. Weigh the same mass of each size. Add the same volume of dilute acid, of the same concentration and in excess, to a flask connected to a gas syringe. Start the timer when the marble is added, and record the volume of gas at frequent intervals early in the reaction. Repeat each run three times. Plot volume against time for each size, and compare the initial slopes [8].\n\n(e) Safety: wear goggles, because dilute hydrochloric acid irritates the eyes and skin. Make sure the gas can leave through the syringe, so pressure cannot build up in the flask [2]. Validity: check the apparatus for leaks, because escaping gas would lower the readings. Check that the syringe can hold all the gas produced; otherwise the plunger reaches its limit and the later readings are lost [2].',
 '(a) Хороший вопрос называет изменяемую переменную (размер частиц, то есть площадь поверхности мрамора), измеряемую величину (начальную скорость выделения CO₂, см³/с) и реакцию. Например: «Как площадь поверхности мраморной крошки влияет на начальную скорость выделения CO₂?» Уравнение реакции: CaCO₃(s) + 2HCl(aq) → CaCl₂(aq) + H₂O(l) + CO₂(g) [3].\n\n(b) Гипотеза: мелкие кусочки дают большую начальную скорость. Кусочки той же массы, но меньшего размера, имеют большую общую площадь поверхности. Кислота чаще касается поверхности твёрдого вещества, поэтому за секунду происходит больше эффективных столкновений и реакция начинается быстрее. Общий объём CO₂ при этом не меняется: одинаковая масса мрамора в избытке кислоты даёт одинаковое количество газа [5].\n\n(c) Независимая переменная — размер частиц мрамора, то есть площадь поверхности. Зависимая переменная — объём CO₂, собранный в первые секунды; по нему находят начальную скорость (см³/с). Контролируемые переменные: масса мрамора, объём и концентрация кислоты (кислота в избытке) и температура. Площадь поверхности напрямую не измеряют, поэтому размер частиц используют как её оценку [5].\n\n(d) Просеять мрамор через сита, получив не меньше пяти фракций определённого размера. Взвесить одинаковую массу каждой фракции. В колбу, соединённую с газовым шприцем (gas syringe), налить одинаковый объём разбавленной кислоты одной концентрации, взятой в избытке. Запустить секундомер в момент добавления мрамора и записывать объём газа часто в начале реакции. Каждый опыт повторить три раза. Построить график «объём — время» для каждой фракции и сравнить начальные наклоны кривых [8].\n\n(e) Безопасность: нужны защитные очки, так как разбавленная соляная кислота раздражает кожу и глаза. Газ должен выходить через шприц, иначе давление в колбе возрастёт [2]. Достоверность: установка должна быть герметичной, так как утечка газа занижает показания. Шприц должен вмещать весь выделившийся газ, иначе поршень дойдёт до предела и последние показания будут потеряны [2].'),
 item('chem-C','C','The results below were obtained with two sizes of marble chips. Times: 0, 10, 20, 30, 40 and 50 s. Small chips give 0, 24, 40, 50, 56 and 60 cm³ of CO₂. Large chips give 0, 12, 23, 33, 42 and 50 cm³. Both sets use the same mass of marble with excess acid. By 50 s, the small chips have produced 60 cm³ of CO₂, but the large chips only 50 cm³.\n\n(a) Plot both curves on the same axes, and calculate the mean rate of reaction for 0–20 s [7].\n\n(b) Compare the early rates and the volumes of CO₂ produced by 50 s. Explain the differences using collision theory [6].\n\n(c) (Extended) Explain why the mean rates in part (a) are not exact initial rates [4].\n\n(d) Evaluate the limitations of this method. Suggest two improvements and explain how each one reduces a limitation [8].','Результаты ниже получены при двух размерах мраморной крошки. Моменты времени: 0, 10, 20, 30, 40 и 50 с. Мелкие кусочки выделили 0, 24, 40, 50, 56 и 60 см³ CO₂. Крупные — 0, 12, 23, 33, 42 и 50 см³. Обе серии взяты с одинаковой массой мрамора и избытком кислоты. К 50 с мелкие кусочки выделили 60 см³ CO₂, а крупные — только 50 см³.\n\n(a) Построй графики обеих кривых на одних осях и вычисли среднюю скорость химической реакции (rate of reaction) за 0–20 с [7].\n\n(b) Сравни начальные скорости и объёмы CO₂, выделившиеся к 50 с. Объясни различия с помощью теории столкновений (collision theory) [6].\n\n(c) (Extended) Объясни, почему средние скорости из части (a) не равны точным начальным скоростям [4].\n\n(d) Оцени ограничения этого метода. Предложи два улучшения и объясни, как каждое из них уменьшает одно ограничение [8].',
 '(a) Axes: time (s) along the horizontal and volume of CO₂ (cm³) along the vertical. Choose a scale that uses most of the grid. Plot each point accurately, draw a smooth curve through the points, and label both curves in a key (small or large chips) [5]. Mean rate for 0–20 s: small chips 40 cm³ ÷ 20 s = 2.0 cm³ s⁻¹; large chips 23 cm³ ÷ 20 s = 1.15 cm³ s⁻¹, or 1.2 cm³ s⁻¹ to 2 significant figures [2].\n\n(b) Early rates (0–10 s): small chips 24 cm³ ÷ 10 s = 2.4 cm³ s⁻¹; large chips 12 cm³ ÷ 10 s = 1.2 cm³ s⁻¹. The small chips start about twice as fast, because their larger surface area means more acid particles reach the solid each second and more collisions are effective. Small chips are ahead at every time after the start: 56 cm³ at 40 s, compared with 42 cm³ for large chips. The final volume depends only on the mass of marble, because the marble is the limiting reactant and the acid is in excess. So both sets should reach 60 cm³ in the end, but by 50 s only the small chips have done so [6].\n\n(c) The mean reaction rate is an average over 20 s, but the reaction rate keeps changing. It is fastest at the start and falls as the chips get smaller and the acid becomes more dilute. The initial rate is the gradient of the curve at t = 0, i.e. the tangent, the straight line that touches the curve at that point. Measuring over a shorter time, or taking more readings at the start, gives a closer estimate [4].\n\n(d) First, gas leaks lower the measured volume, so the rate is underestimated. Second, a delay between adding the marble and starting the timer makes the early readings unreliable. Third, friction in the gas syringe causes sticking and reading errors. Fourth, readings every 10 s miss the fastest part of the reaction [4]. Improvements: (1) check that the apparatus is airtight before each run, which reduces leaks; (2) start the timer when the marble is added and take readings every 5 s at the start. Alternatively, use a gas pressure or volume sensor with a data logger, which records continuously and reduces reading errors [4].',
 '(a) Оси: время (с) по горизонтали, объём CO₂ (см³) по вертикали. Масштаб выбирают так, чтобы график занимал почти всю сетку. Точки наносят аккуратно, кривые проводят плавно, а обе кривые подписывают в условных обозначениях (мелкие или крупные кусочки) [5]. Средняя скорость за 0–20 с: мелкие кусочки — 40 см³ ÷ 20 с = 2,0 см³/с. Крупные — 23 см³ ÷ 20 с = 1,15 см³/с, или 1,2 см³/с с двумя значащими цифрами [2].\n\n(b) Начальные скорости (0–10 с): мелкие кусочки — 24 см³ ÷ 10 с = 2,4 см³/с. Крупные — 12 см³ ÷ 10 с = 1,2 см³/с. Мелкие кусочки начинают примерно вдвое быстрее. У них больше общая площадь поверхности, поэтому кислота чаще касается твёрдого вещества, и за секунду происходит больше эффективных столкновений. Мелкие кусочки опережают крупные в каждый момент после начала: при 40 с они выделили 56 см³, а крупные — 42 см³. Конечный объём зависит только от массы мрамора, потому что мрамор — вещество в недостатке (limiting reactant), а кислота в избытке. Поэтому в итоге обе серии должны дать 60 см³, но к 50 с это успели сделать только мелкие кусочки [6].\n\n(c) Средняя скорость — это среднее за 20 с, а скорость реакции всё время меняется. В начале она наибольшая, затем падает, потому что кусочки становятся меньше, а кислота разбавляется. Начальная скорость — это угловой коэффициент касательной к кривой при t = 0. Касательная — прямая, которая касается кривой в этой точке. Чем короче промежуток времени и чем чаще отсчёты в начале, тем точнее оценка [4].\n\n(d) Первое ограничение: утечки газа занижают объём, поэтому скорость получается ниже. Второе: задержка между добавлением мрамора и запуском таймера искажает первые показания. Третье: трение поршня шприца даёт ошибки отсчёта. Четвёртое: отсчёт раз в 10 с пропускает самую быструю часть реакции [4]. Улучшения: (1) перед каждым опытом проверять герметичность установки, что уменьшает утечки; (2) запускать таймер в момент добавления мрамора и снимать показания раз в 5 с. Можно также использовать датчик давления или объёма с регистратором данных (data logger): он записывает показания непрерывно и уменьшает ошибки отсчёта [4].'),
 item('chem-D','D','An aluminium plant compares two ways of producing 1000 kg of aluminium: primary extraction from ore, which needs 14 kWh per kg, and recycling scrap, which needs 0.8 kWh per kg.\n\n(a) Explain how Al³⁺ ions are reduced, the role of cryolite, and why carbon anodes are used [8].\n\n(b) Calculate the energy saved by recycling 1000 kg. Explain two environmental or economic factors that affect the choice [7].\n\n(c) Suggest a strategy for aluminium supply. Evaluate the effects of contamination, the collection of scrap and the limits of the data [10].','Завод сравнивает два способа получить 1000 кг алюминия. Первичное получение из руды требует 14 кВт·ч на килограмм, переплавка лома — 0,8 кВт·ч на килограмм.\n\n(a) Объясни, как происходит восстановление (reduction) ионов Al³⁺, какую роль играет криолит (cryolite) и зачем нужны угольные аноды (anodes) [8].\n\n(b) Вычисли энергию, которую экономит переплавка 1000 кг. Объясни два экологических или экономических фактора, которые влияют на выбор [7].\n\n(c) Предложи стратегию снабжения алюминием. Оцени влияние загрязнения, сбора лома и ограничений данных [10].',
 '(a) At the cathode, each Al³⁺ ion gains three electrons, which is reduction: Al³⁺(l) + 3e⁻ → Al(l). The electric current supplies the electrons, so the reaction needs electricity. Aluminium oxide has a very high melting point, about 2050 °C. Dissolving it in molten cryolite (Na₃AlF₆) lowers the operating temperature to about 950 °C and gives a melt that conducts electricity. Carbon is used for the anodes because it conducts electricity well and is cheap. At the carbon anode, oxide ions lose electrons, which is oxidation: 2O²⁻(l) → O₂(g) + 4e⁻. The oxygen reacts with the carbon: C(s) + O₂(g) → CO₂(g). The carbon anodes are used up, and CO₂ is released [8].\n\n(b) Primary extraction: 14 kWh/kg × 1000 kg = 14 000 kWh. Recycling: 0.8 kWh/kg × 1000 kg = 800 kWh. Energy saved: 14 000 kWh − 800 kWh = 13 200 kWh, which is about 94% of the primary energy (13 200 ÷ 14 000 × 100) [3]. Electricity source [2]: if the current comes from burning fossil fuels, each kWh releases a lot of CO₂, so the emission saving depends on the energy mix. Collection and sorting [2]: scrap must be gathered, transported and sorted, which costs money and energy, so the real saving can be smaller than the calculated one.\n\n(c) A sensible strategy is to recycle clean scrap of a known alloy first, because contaminated scrap is hard to reuse. Collection should be extended to raise the supply, but scrap cannot meet all the demand, so primary production will still be needed. Contamination, for example paint or other metals, lowers the quality of the recycled metal. The figures leave out some stages of the life cycle and carry uncertainty. The 94% applies only to the process energy in this example, so it is not a general life-cycle figure. Conclusion: recycling saves most energy if clean scrap can be collected close to the plant; otherwise the saving is smaller [10].',
 '(a) На катоде каждый ион Al³⁺ присоединяет три электрона. Это восстановление: Al³⁺(l) + 3e⁻ → Al(l). Электроны поступают от источника тока, и без тока реакция не идёт. Оксид алюминия имеет очень высокую температуру плавления (около 2050 °C). Его растворяют в расплавленном криолите (Na₃AlF₆): рабочая температура падает примерно до 950 °C, а расплав начинает проводить ток. Для анодов берут углерод, потому что он хорошо проводит ток и недорог. На угольном аноде ионы кислорода отдают электроны. Это окисление: 2O²⁻(l) → O₂(g) + 4e⁻. Кислород реагирует с углеродом: C(s) + O₂(g) → CO₂(g). Поэтому угольные аноды расходуются, и выделяется CO₂ [8].\n\n(b) Первичное получение: 14 кВт·ч/кг × 1000 кг = 14 000 кВт·ч. Переплавка: 0,8 кВт·ч/кг × 1000 кг = 800 кВт·ч. Экономия: 14 000 кВт·ч − 800 кВт·ч = 13 200 кВт·ч, что составляет примерно 94 % энергии первичного получения (13 200 ÷ 14 000 × 100) [3]. Источник электроэнергии [2]: если ток вырабатывают при сжигании ископаемого топлива, каждый кВт·ч даёт много CO₂, поэтому выгода по выбросам зависит от того, как вырабатывают ток. Сбор и сортировка [2]: лом нужно собрать, перевезти и рассортировать, а это стоит денег и энергии, поэтому реальная экономия может быть меньше расчётной.\n\n(c) Разумная стратегия — сначала перерабатывать чистый лом известного сплава, потому что загрязнённый лом трудно использовать повторно. Сбор лома стоит расширять, но лома не хватит на весь спрос, поэтому первичное производство останется нужным. Загрязнения, например краска или другие металлы, снижают качество переработанного металла. Цифры не учитывают часть этапов жизненного цикла и содержат неопределённость. Значение 94 % относится только к энергии самого процесса в этом примере, поэтому это не общая оценка для всего жизненного цикла. Вывод: переработка экономит больше всего энергии, если чистый лом можно собрать рядом с заводом; иначе экономия меньше [10].'),
 ]},
];
